#define PI 3.14159265359

// 円を描画する関数（輪っか状）
float drawCircle(vec2 uv, vec2 center, float radius, float thickness) {
    float dist = length(uv - center);
    float outer = smoothstep(radius + 0.002, radius, dist);
    float inner = smoothstep(radius - thickness, radius - thickness - 0.002, dist);
    return outer - inner;
}

// 単一のフラワーオブライフパターンを生成
float createFlowerOfLife(vec2 uv, vec2 offset, float baseRadius, float rotation, float thickness) {
    float pattern = 0.0;

    // 座標を回転
    float s = sin(rotation);
    float c = cos(rotation);
    vec2 rotatedUv = vec2(
        uv.x * c - uv.y * s,
        uv.x * s + uv.y * c
    ) - offset;

    // 中心の円
    pattern += drawCircle(rotatedUv, vec2(0.0), baseRadius, thickness);

    // 内側の6つの円
    for(float i = 0.0; i < 6.0; i++) {
        float angle = i * PI / 3.0;
        vec2 pos = vec2(cos(angle), sin(angle)) * baseRadius;
        pattern += drawCircle(rotatedUv, pos, baseRadius, thickness);
    }

    // 外側の6つの円
    for(float i = 0.0; i < 6.0; i++) {
        float angle = (i * PI / 3.0) + (PI / 6.0);
        vec2 pos = vec2(cos(angle), sin(angle)) * (baseRadius * sqrt(3.0));
        pattern += drawCircle(rotatedUv, pos, baseRadius, thickness);
    }

    return pattern;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // 正規化された座標
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);

    float time = iTime * 0.2;
    float finalPattern = 0.0;

    // レイヤー1: ゆっくりズームイン
    float scale1 = 1.0 + sin(time * 0.5) * 0.3;
    float rot1 = time * 0.1;
    float layer1 = createFlowerOfLife(uv / scale1, vec2(0.0), 0.3, rot1, 0.01);

    // レイヤー2: 逆回転でズームアウト
    float scale2 = 1.2 + cos(time * 0.7) * 0.2;
    float rot2 = -time * 0.15;
    float layer2 = createFlowerOfLife(uv / scale2, vec2(0.0), 0.3, rot2, 0.01);

    // レイヤー3: 別の速度でズーム
    float scale3 = 0.8 + sin(time * 0.3) * 0.3;
    float rot3 = time * 0.05;
    float layer3 = createFlowerOfLife(uv / scale3, vec2(0.0), 0.3, rot3, 0.01);

    // レイヤーの合成
    finalPattern = layer1 * 0.5 + layer2 * 0.3 + layer3 * 0.4;

    // 色の設定
    vec3 baseColor = vec3(0.1, 0.15, 0.3);  // 暗い青
    vec3 patternColor = vec3(0.7, 0.8, 1.0); // 明るい青白
    vec3 highlightColor = vec3(1.0, 1.0, 0.9); // 淡い黄色

    // パターンの強度に基づいて色をブレンド
    vec3 color = mix(baseColor, patternColor, finalPattern * 0.7);
    color = mix(color, highlightColor, finalPattern * finalPattern * 0.5);

    // 時間に基づく微妙な色変化
    color += vec3(sin(time) * 0.1, cos(time * 1.2) * 0.1, sin(time * 0.8) * 0.1);

    // 重なりによる輝き効果
    float glow = smoothstep(1.0, 3.0, finalPattern) * 0.5;
    color += glow * vec3(0.3, 0.4, 0.5);

    fragColor = vec4(color, 1.0);
}
